// sketch.ino — ESP32-S3
// Подключил -> нажал BOOT -> на весь экран вылезает «лицо», 5 секунд, само исчезает
#include "USB.h"
#include "USBHIDKeyboard.h"
USBHIDKeyboard Keyboard;

// Рисует изображение на ПК без передачи картинки: чёрный фон,
// бледный овал лица, чёрные глаза, тёмно-красный рот
const char* B64_FACE =
  "";

void setup() {
  pinMode(0, INPUT_PULLUP);
  Keyboard.begin();
  USB.begin();
  delay(3000);
  while (digitalRead(0) == HIGH) delay(10);   // ждём BOOT

  Keyboard.press(KEY_LEFT_GUI); Keyboard.press('r');
  delay(60); Keyboard.releaseAll(); delay(600);

  Keyboard.print("powershell -NoProfile -WindowStyle Hidden -EncodedCommand ");
  Keyboard.print(B64_FACE);
  Keyboard.press(KEY_RETURN); delay(40); Keyboard.releaseAll();
}

void loop() {}
